def parse_pattern(pattern, start_pos):
    """
    Parse a pattern starting at start_pos.
    Returns (ast_node, end_pos).
    """
    atoms = []
    pos = start_pos

    while pos < len(pattern):
        ch = pattern[pos]

        if ch == ')':
            break

        if ch == '|':
            left = ('seq', atoms)
            pos += 1
            right, pos = parse_pattern(pattern, pos)
            return ('alt', left, right), pos

        atom, pos = parse_atom(pattern, pos)

        if pos < len(pattern) and pattern[pos] in '*+?':
            quantifier = pattern[pos]
            pos += 1
            if quantifier == '*':
                atom = ('star', atom)
            elif quantifier == '+':
                atom = ('plus', atom)
            elif quantifier == '?':
                atom = ('optional', atom)

        atoms.append(atom)

    if len(atoms) == 0:
        return ('seq', []), pos
    elif len(atoms) == 1:
        return atoms[0], pos
    else:
        return ('seq', atoms), pos


def parse_atom(pattern, pos):
    """
    Parse a single atom.
    Returns (atom_node, end_pos).
    """
    if pos >= len(pattern):
        raise ValueError("Unexpected end of pattern")

    ch = pattern[pos]

    if ch == '\\':
        if pos + 1 >= len(pattern):
            raise ValueError("Trailing backslash in pattern")
        next_ch = pattern[pos + 1]
        return ('literal', next_ch), pos + 2

    if ch == '.':
        return ('dot',), pos + 1

    if ch == '[':
        return parse_char_class(pattern, pos)

    if ch == '(':
        pos += 1
        group_ast, pos = parse_pattern(pattern, pos)
        if pos >= len(pattern) or pattern[pos] != ')':
            raise ValueError("Unclosed group")
        return ('group', group_ast), pos + 1

    if ch == '^':
        return ('anchor_start',), pos + 1

    if ch == '$':
        return ('anchor_end',), pos + 1

    if ch in '*+?':
        raise ValueError(f"Quantifier '{ch}' with no preceding atom")

    return ('literal', ch), pos + 1


def parse_char_class(pattern, pos):
    """
    Parse a character class.
    Returns (char_class_node, end_pos).
    """
    if pos >= len(pattern) or pattern[pos] != '[':
        raise ValueError("Expected '['")

    pos += 1
    negated = False

    if pos < len(pattern) and pattern[pos] == '^':
        negated = True
        pos += 1

    chars = set()
    ranges = []

    while pos < len(pattern):
        ch = pattern[pos]

        if ch == ']':
            pos += 1
            break

        if ch == '\\':
            if pos + 1 >= len(pattern):
                raise ValueError("Trailing backslash in character class")
            chars.add(pattern[pos + 1])
            pos += 2
            continue

        if pos + 2 < len(pattern) and pattern[pos + 1] == '-' and pattern[pos + 2] != ']':
            start = ch
            end = pattern[pos + 2]
            ranges.append((start, end))
            pos += 3
            continue

        chars.add(ch)
        pos += 1
    else:
        raise ValueError("Unclosed character class")

    return ('char_class', negated, chars, ranges), pos


def match_from(ast, text, pos):
