        ch = text[pos]

        in_class = ch in chars
        for start, end in ranges:
            if ord(start) <= ord(ch) <= ord(end):
                in_class = True
                break

        if negated:
            in_class = not in_class

        if in_class:
            return pos + 1
        return None

    elif ast[0] == 'anchor_start':
        if pos == 0:
            return pos
        return None

    elif ast[0] == 'anchor_end':
        if pos == len(text):
            return pos
        return None

    elif ast[0] == 'group':
        return match_from(ast[1], text, pos)

    elif ast[0] == 'seq':
        current_pos = pos
        for atom in ast[1]:
            current_pos = match_from(atom, text, current_pos)
            if current_pos is None:
                return None
        return current_pos

    elif ast[0] == 'alt':
        result = match_from(ast[1], text, pos)
        if result is not None:
            return result
        return match_from(ast[2], text, pos)

    elif ast[0] == 'star':
        atom = ast[1]
