        first_match = match_from(atom, text, pos)
        if first_match is None:
            return None
        # Then try to match zero or more
        return match_star_greedy(atom, text, first_match)

    elif ast[0] == 'optional':
        # Try matching once
        result = match_from(ast[1], text, pos)
        if result is not None:
            return result
        # Try matching zero times
        return pos

    raise ValueError(f"Unknown AST node: {ast[0]}")


def match_star_greedy(atom, text, pos):
    """
    Match atom zero or more times greedily.
    Returns the position after matching, supporting backtracking.
    This is a special marker that indicates we should try all possibilities.
    """
    # Collect all possible end positions
    positions = [pos]
    current_pos = pos

    while current_pos < len(text):
        next_pos = match_from(atom, text, current_pos)
        if next_pos is None:
            break
        positions.append(next_pos)
        current_pos = next_pos

    # Return a special object that indicates we have multiple possibilities
    return ('star_result', positions)


