def match_sequence(atoms, text, pos):
    """
    Match a sequence of atoms.
    Handles backtracking for quantifiers in the sequence.
    """
    if len(atoms) == 0:
        return pos

    if len(atoms) == 1:
        return match_from(atoms[0], text, pos)

    first_atom = atoms[0]
    rest_atoms = atoms[1:]

    # Special handling for star/plus in first position
    if first_atom[0] in ('star', 'plus'):
        atom = first_atom[1]

        # Collect all possible positions after matching the quantified atom
        if first_atom[0] == 'star':
            positions = [pos]
        else:  # plus
            first_match = match_from(atom, text, pos)
            if first_match is None:
                return None
            positions = [first_match]

