        for try_pos in reversed(positions):
            rest_result = match_sequence(rest_atoms, text, try_pos)
            if rest_result is not None:
                return rest_result

        return None

    # Normal case: match first atom, then rest
    first_result = match_from(first_atom, text, pos)
    if first_result is None:
        return None

    return match_sequence(rest_atoms, text, first_result)


def match_star_backtrack(atom, text, pos):
    """
    Match atom zero or more times with backtracking support.
    This is called when we need to match a star/plus and there are more atoms after it.
    But since we're in match_from which is called for a single atom,
    we just match greedily here and let the sequence handler do backtracking.
    """
    current_pos = pos
    while current_pos < len(text):
        next_pos = match_from(atom, text, current_pos)
        if next_pos is None:
            break
        current_pos = next_pos
    return current_pos
